function panels(root,list,def){
  var bar=document.createElement('div');bar.className='chips';bar.setAttribute('role','tablist');
  var host=document.createElement('div');host.className='panel';
  root.appendChild(bar);root.appendChild(host);
  function open(id){
    var p=list.filter(function(x){return x[0]===id})[0]||list[0];
    [].forEach.call(bar.children,function(b){b.setAttribute('aria-selected',b.dataset.id===p[0])});
    host.innerHTML='<h3 class="ph">'+esc(p[1])+'</h3>'+p[2].html;
    if(p[2].init)p[2].init(host);
    store.set('sub_'+root.getAttribute('data-view'),p[0])}
  list.forEach(function(p){var b=document.createElement('button');b.type='button';b.className='chip';b.dataset.id=p[0];b.setAttribute('role','tab');b.textContent=p[1];b.onclick=function(){open(p[0])};bar.appendChild(b)});
  root.addEventListener('spa-open',function(e){open(e.detail)});
  open(store.get('sub_'+root.getAttribute('data-view'),def||list[0][0]));
}
