P.push(['groups','Groups and their public positions',{html:'<p class="sub"><b>This site takes no side.</b> This is a list of organizations that have publicly said something about plate readers, in the direction they said it, with a link to their own words. It is not complete, it is not an endorsement or a ranking, and I am not joining any coalition. If a group is missing, email me the link and I will add it with the same neutral wording, whichever way it leans.</p>'+tbl(['Group','Public stance (as reported)','Source'],[['ACLU of Wisconsin','Has asked for limits, including a request that the Wisconsin Supreme Court require warrants for plate reader data, and has commented on Dane County\'s vote to defund Flock.','<a href="https://www.aclu-wi.org/press-releases/aclu-of-wisconsin-issues-statement-following-dane-county-board-vote-to-defund-flock/" target="_blank" rel="noopener">ACLU-WI statement</a>; <a href="https://fox11online.com/news/local/wi-aclu-lawsuit-asks-supreme-court-to-require-warrants-for-license-plate-reader-data" target="_blank" rel="noopener">FOX 11 report</a>'],['Institute for Justice','Is suing over Norfolk, Virginia\'s Flock camera network and has called Flock\'s proposed reforms "window dressing" (Aug 13, 2026).','<a href="https://ij.org/press-release/institute-for-justice-calls-flock-safetys-proposed-reforms-window-dressing/" target="_blank" rel="noopener">IJ press release</a>'],['Flock Safety','The vendor of the current cameras. Offers its product to police and has proposed reforms to its own practices.','Same IJ release links to its proposals; see Flock\'s own site for its statements'],['Sun Prairie Police Department','Uses plate readers, plans to switch to Axon, and has promised added safeguards (see Promises).','Chief\'s FAQ (archive p. 249–256)'],['Wisconsin legislators','A bill (2025 AB 576) was introduced to limit police use of plate readers. Check the Legislature\'s site for its status.','<a href="https://lobbying.wi.gov/What/BillInformation/2025REG/BillKey/REGAB576" target="_blank" rel="noopener">Wisconsin lobbying page</a>'],['Police associations (e.g., Wisconsin Professional Police Association)','I looked and could not confirm a published position on plate readers. I am not guessing one.','—']])+'<p class="sub">Last checked Nov 11, 2026. Positions change; read the sources.</p>'}]);
P.push(['dl','Data download',{html:'<p class="sub">Plain files you can keep and use. Everything here already appears on this site or in the Advocacy Records.</p><div class="row"><button class="btn ghost" id="d1" type="button">Numbers (CSV)</button><button class="btn ghost" id="d2" type="button">Promises (CSV)</button><button class="btn ghost" id="d3" type="button">Email index (CSV)</button><button class="btn ghost" id="d4" type="button">Timeline (CSV)</button></div>',init:function(h){var g=function(id,fn){h.querySelector(id).onclick=fn};g('#d1',function(){load('tracker').then(function(T){dl('numbers.csv',csv([['figure','what','as_of','source']].concat(T.numbers)),'text/csv')})});g('#d2',function(){load('tracker').then(function(T){dl('promises.csv',csv([['who','commitment','when','status']].concat(T.promises.map(function(p){return p.slice(0,4)}))),'text/csv')})});g('#d3',function(){load('emails').then(function(E){dl('email-index.csv',csv([['id','title','date','from','to','archive_page','topics']].concat(E.map(function(e){return[e.id,e.t,e.d,e.f,e.to,e.p,e.tg.join('; ')]}))),'text/csv')})});g('#d4',function(){load('tracker').then(function(T){dl('timeline.csv',csv([['date','event']].concat(T.timeline)),'text/csv')})})}}]);
S.panels(hub,P,'prom');
