function netform(h,sel,name){var f=h.querySelector(sel);f.addEventListener('submit',function(e){e.preventDefault();var st=f.querySelector('.status'),btn=f.querySelector('button[type=submit]');btn.disabled=true;st.textContent='Sending…';var d=new FormData(f);d.append('form-name',name);fetch('/',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(d).toString()}).then(function(r){if(!r.ok)throw 0;st.textContent='Thanks, it was sent.';f.reset()}).catch(function(){st.textContent='It did not send (this only works on the live site). Please email sunprairiealpr@gmail.com.'}).then(function(){btn.disabled=false})})}
var NOTE='<p class="sub">This site is independent and unofficial. I am not affiliated with the City of Sun Prairie or the Sun Prairie Police Department. I have met Chief Kevin Warych several times and stay independent. Contact: sunprairiealpr@gmail.com · 608-940-7356 · Facebook "Zack Mark" · Instagram @sunprairiealpr.</p>';
/* ===== Methods & trust ===== */
var m=S.mkView('method','Methods & trust','How I gather facts, how sure I am, and what I disclose. If something here is wrong, tell me and I will fix it and log it.','','About this site');
var P=[];
P.push(['meth','How I work',{html:'<ol class="steps2"><li><b>Primary sources first.</b> Contracts, policies, agendas, quotes and emails I received. Headlines are labeled as headlines.</li><li><b>Statement vs term.</b> What an official said is not the same as what a contract or policy says. I mark both.</li><li><b>Dates on everything.</b> Facts carry an "as of" date. Pending means the condition has not arrived.</li><li><b>Officials\' emails are copied as written.</b> I do not edit them.</li><li><b>No predictions.</b> I do not predict votes or outcomes.</li><li><b>No faces, plates or private people.</b> I do not post real plate numbers, photos of residents or officers, or personal details about staff or residents.</li><li><b>Corrections.</b> Errors are mine to fix, and I log them.</li></ol>'}]);
P.push(['lab','Source labels',{html:tbl(['Label','Means','Example'],[['<span class="pill kept">A. Document</span>','The official document itself','Policy F-18; the Axon quote'],['<span class="pill stmt">B. Official statement</span>','Said or emailed by an official; not yet a written term','The Chief\'s Oct 27 promises'],['<span class="pill open">C. News report</span>','A news outlet\'s reporting, not checked by me','Kenosha headlines'],['<span class="pill pend">D. My note</span>','My own summary or question','The "Still unanswered" list']])}]);
P.push(['sure','How sure are we?',{html:'<p class="sub">A plain meter for key facts.</p>'+tbl(['Fact','How sure','Why'],[['Flock retention is 30 days','<span class="meter" style="--v:5"></span> High','Written in Policy F-18'],['Axon estimate is $235,388.97 over 10 years','<span class="meter" style="--v:4"></span> High as an estimate; not a final price','Axon quote; it says non-binding'],['Axon retention will start at 14 days','<span class="meter" style="--v:2"></span> Medium','Chief\'s statement; pending approval'],['No livestreaming','<span class="meter" style="--v:2"></span> Medium','Statement; pending contract and policy'],['No sharing with 287(g) agencies','<span class="meter" style="--v:2"></span> Medium','SPPD FAQ; not yet a contract term'],['Monthly audits by a Detective Sergeant','<span class="meter" style="--v:2"></span> Medium','Statement; F-18 itself names the System Administrator'],['Flock audit logs kept after Flock ends','<span class="meter" style="--v:1"></span> Unknown','Asked Oct 27; no answer yet']])}]);
P.push(['chk','Last checked',{html:tbl(['Page','Last checked'],[['Trackers and numbers','Nov 10, 2026'],['Policy F-18 explorer','Nov 10, 2026 (policy updated Mar 3, 2026)'],['Groups and positions','Nov 11, 2026'],['Other cities','Nov 10, 2026'],['Speak up (meeting details)','Nov 10, 2026. Check the official agenda; times change.']])+'<p class="sub">If a date here is old, the page may be out of date. Email me.</p>'}]);
P.push(['corr','Corrections',{html:'<p>Found an error? Email <b>sunprairiealpr@gmail.com</b> with "Correction" in the subject, or use the form. I will fix it, say what changed in the What changed list, and log it.</p><form class="formcard" id="cf" method="POST"><p class="hp" style="position:absolute;left:-9999px"><label>Leave empty <input name="bot-field" tabindex="-1" autocomplete="off"></label></p><label>Which page and what is wrong?<textarea name="correction" rows="3" required></textarea></label><label>Link to a source (optional)<input name="source"></label><label>Email (optional)<input name="email" type="email"></label><button class="btn primary" type="submit">Send correction</button><p class="status" role="status"></p></form>',init:function(h){netform(h,'#cf','correction')}}]);
P.push(['rev','Reader review',{html:'<p class="sub">Tell me what was clear, what was not, and what is missing. I read these and change the site.</p><form class="formcard" id="rf" method="POST"><p class="hp" style="position:absolute;left:-9999px"><label>Leave empty <input name="bot-field" tabindex="-1" autocomplete="off"></label></p><label>Which page?<input name="page"></label><label>How clear was it? (1 to 5)<input name="clarity" type="number" min="1" max="5"></label><label>What would make it better?<textarea name="comment" rows="3"></textarea></label><button class="btn primary" type="submit">Send review</button><p class="status" role="status"></p></form><h4>Report a site error</h4><form class="formcard" id="ef" method="POST"><p class="hp" style="position:absolute;left:-9999px"><label>Leave empty <input name="bot-field" tabindex="-1" autocomplete="off"></label></p><label>What went wrong (broken link, layout, etc.)?<textarea name="error" rows="3" required></textarea></label><button class="btn primary" type="submit">Send error report</button><p class="status" role="status"></p></form>',init:function(h){netform(h,'#rf','reader-review');netform(h,'#ef','error-report')}}]);
P.push(['fact','Independent fact-check',{html:'<p>I welcome an independent fact-checker, such as a teacher, librarian, journalist or student press editor, to check the numbers on the Trackers page against the Advocacy Records. No one has done this yet, so I do not claim it. To volunteer, email sunprairiealpr@gmail.com. A checker\'s name is shown only if they agree.</p>'}]);
P.push(['trans','Transparency statement',{html:'<h4>2026 statement</h4><ul><li><b>Independence.</b> This record and both projects are independent and student-led. They are not affiliated with, approved by, or speaking for the Sun Prairie Area School District, the City of Sun Prairie, or the Sun Prairie Police Department.</li><li><b>Funding.</b> No one pays for this work, and no organization sponsors it.</li><li><b>AI use.</b> Zackary uses AI tools to help draft, organize and format writing, including parts of this record. Facts, quotes and numbers are checked against the original emails and documents.</li><li><b>Conflicts.</b> I am a student at Sun Prairie West High School. I have met Chief Kevin Warych several times while staying independent. I am open about questions I have asked officials, and my questions and their answers are published in the record. If you think I have a conflict I have not listed, tell me.</li><li><b>Corrections.</b> Logged at the back of the Advocacy Records and in What changed.</li></ul><p class="sub">The wording for independence, funding and AI use is from the Advocacy Records appendix (p. 330). I will publish an updated statement each year.</p>'}]);
P.push(['ai','AI use',{html:'<p>Zackary uses AI tools to help draft, organize and format writing, including parts of this record and this site. Facts, quotes and numbers are checked against the original emails and documents, and officials\' emails are copied as written. AI does not speak for anyone here. I do not use AI to create quotes or voices, and I do not post AI-made images of real people. If you find an error, it is mine to fix.</p>'}]);
P.push(['priv','Privacy in plain words',{html:'<ul><li>I do not run analytics or ad trackers on this site, and I do not sell or share data.</li><li>The site loads its fonts from Google Fonts, so your browser contacts Google to get them. No other third-party scripts run here.</li><li>Your reading choices (text size, theme, favorites, notes, highlights, badges, quiz progress) are stored only in your own browser, on your own device.</li><li>If you send a form (contact, questions, corrections), it is delivered through my site host, Netlify, to me. I read it and keep it only as long as needed to answer. I do not publish names or emails.</li><li>My host may keep standard server logs, like any web host.</li><li>I do not ask for your address, and I do not collect information on children.</li><li>To clear what the site stored in your browser, use "Clear my saved data" in the Reading tools.</li></ul>'}]);
P.push(['acc','Accessibility',{html:'<p>I want everyone to be able to use this site. What is built in: keyboard navigation, a skip link, visible focus, text size and spacing controls, light, dark and sepia themes, a dyslexia-friendly spacing preset, large tap targets, a reduced-motion switch, focus mode, read-aloud using your device\'s voice, print-friendly pages, easy-read and Spanish versions.</p><p><b>What I have not done:</b> I have not had the site tested with every screen reader or by an accessibility auditor. If something does not work for you, please tell me what you use and what happened, and I will fix it. Email sunprairiealpr@gmail.com.</p>'}]);
P.push(['ver','Verified sources',{html:'<p>A <span class="pill kept">Official source</span> badge means the link goes to a government or vendor document itself (not a news story about it). Official sources I use:</p><ul><li>SPPD Policy F-18, SPPD FAQ and Axon quote Q-932192-001 (copies in the Advocacy Records, p. 213–256).</li><li>The city\'s records portal: <a href="https://sunprairiewi.justfoia.com/Forms/Launch/df6bbb83-0689-418b-afc3-b0f5b92d142e" target="_blank" rel="noopener">police records request form</a>.</li><li>Wisconsin voter information: <a href="https://myvote.wi.gov" target="_blank" rel="noopener">myvote.wi.gov</a>.</li></ul>'}]);
P.push(['news','Newsletter archive',{html:'<p class="sub">No issues have been sent yet. When I send one, it will be listed here with its date and a link, and the same text is on the site. You can sign up on the Join page.</p><p><button class="btn ghost" data-go="join" type="button">Sign up</button></p>'}]);
P.push(['oped','Op-ed library',{html:'<p class="sub">Templates, not opinions. Fill in your own view in your own words. Newspapers set their own length limits.</p><details><summary>150 words</summary><pre class="out">[Hook: one concrete fact]. [One sentence on what you want residents to know]. [One question you want answered]. [One action: attend, ask, read]. [Your name, town, and how to reach you.]</pre></details><details><summary>300 words</summary><pre class="out">[Opening: a specific moment or fact]\n[Background in two sentences: what is proposed, by whom, when]\n[Your main point with one source]\n[A counterpoint you take seriously, and your response]\n[Your ask, with a date]\n[Name and town]</pre></details><details><summary>600 words</summary><pre class="out">[Opening scene or number]\n[What is happening: dates, dollar figures, documents]\n[Why it matters to you personally]\n[Point 1 with source]\n[Point 2 with source]\n[Strongest opposing view, fairly stated]\n[Your answer to it]\n[What readers can do this week]\n[Name, town, disclosure of any connection to the issue]</pre></details>'}]);
P.push(['press','Press release template',{html:'<pre class="out">FOR IMMEDIATE RELEASE · [Date]\nContact: sunprairiealpr@gmail.com · 608-940-7356\n\n[Headline: a plain fact, no adjectives]\n\nSUN PRAIRIE, Wis. — [One-sentence news: what happened, when, where].\n\n[Two short paragraphs of facts with sources.]\n\n"[Quote, with the speaker\'s name and role.]"\n\nAbout: The Sun Prairie ALPR site is an independent, student-run resource that tracks the plate reader program with sources. It is not affiliated with the City of Sun Prairie or the Sun Prairie Police Department. It is not funded by any organization.\n\n###</pre>'}]);
